const fs = require("node:fs");
const vm = require("node:vm");
const path = require("node:path");
const context = vm.createContext({ console, setTimeout, clearTimeout });
context.window = context;
const html = fs.readFileSync("test/index.html", "utf8").replace(/<!--[\s\S]*?-->/g, "");
let checks = 0;
for (const match of html.matchAll(/<script src="([^"]+)"[^>]*>/g)) {
  const filename = path.join("test", match[1]);
  vm.runInContext(fs.readFileSync(filename, "utf8"), context, { filename });
  if (/^test-/.test(match[1])) checks++;
}
if (checks === 0) throw Error("No upstream browser tests discovered");
console.log("Passed browser test files:", checks);
